def count_partitions(n: int, k: int, x: int) -> int:
    if n < x * k or k < 1 or x < 1:
        return 0
    if n == x and k == 1:
        return 1
    if k == 1:
        return 1
    result = 0
    for i in range(x, n + 1):
        result += count_partitions(n - i, k - 1, i)
    return result

def count_sequences(n: int, last: int, memo: dict) -> int:
    if n in memo:
        return memo[n]
    if n == last:
        return 1
    next_numbers = [i for i in range(1, int(last / 2) + 1) if i not in memo]
    if not next_numbers:
        return 0
    counts = [count_sequences(n + i, i, memo) for i in next_numbers]
    return sum(counts)

