def hanoi_double_iterative(n: int) -> int:
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n == 1:
        return 2
    if n == 2:
        return 6
    if n == 3:
        return 14

    # Implement the iterative algorithm for n > 3
    moves = [0] * (n + 1)
    moves[1] = 2
    moves[2] = 6
    moves[3] = 14
    for i in range(4, n + 1):
        moves[i] = moves[i - 1] + moves[i - 2] * 2
    return moves[n]

